import { Injectable, inject } from '@angular/core';
import { NavigationEnd, Router } from '@angular/router';
import { filter, map, tap } from 'rxjs/operators';
import { DataStore } from '../../utils/data-store';
import { RouteBasedCultureUrlService } from '@abp/ng.core';

import { LpxNavbarItem } from './models';
import { LPX_MENU_ITEMS } from './navbar.token';
import { createGroupMap } from '../../utils';
import { OTHERS_GROUP_KEY } from '../../consts';

@Injectable({
  providedIn: 'root',
})
export class NavbarService {
  protected readonly router = inject(Router);
  menuItems = inject(LPX_MENU_ITEMS);
  protected readonly routeCultureUrl = inject(RouteBasedCultureUrlService);

  private store = new DataStore<LpxNavbarItem[]>(
    this.addContainerLinks(this.menuItems),
  );

  /** Skips re-cloning the tree when expand would apply the same location again. */
  private expandedLocationKey: string | null = null;

  navbarItems$ = this.store.sliceState((state) => state);

  // Source reference to navbar items, used for checking item existence
  // without being affected by potential future transformations of navbarItems$
  sourceNavbarItems$ = this.navbarItems$;

  groupedNavbarItems$ = this.store
    .sliceState((state) => state)
    .pipe(
      map((items) => {
        if (!items.some((f) => !!f.group)) {
          return;
        }

        const map = createGroupMap(items, OTHERS_GROUP_KEY) || [];
        return Array.from(map, ([group, items]) => ({
          group,
          items,
        }));
      }),
    );

  constructor() {
    this.expandItemByLink$().subscribe();
  }

  addNavbarItems(...menuItems: LpxNavbarItem[]): void {
    this.expandedLocationKey = null;
    this.store.set([...this.store.state, ...this.addContainerLinks(menuItems)]);
  }

  setNavbarItems(...menuItems: LpxNavbarItem[]): void {
    this.expandedLocationKey = null;
    this.store.set([...this.addContainerLinks(menuItems)]);
    this.expandItems();
  }

  addChildren(id: string, ...menuItems: LpxNavbarItem[]): void {
    const { location } = this.findById(id, this.store.state);

    // If the parent item is not found, do nothing.
    if (!location.length) {
      return;
    }

    const updated = this.addChildrenByLocation(
      this.store.state,
      [...location],
      '',
      menuItems,
    );

    this.expandedLocationKey = null;
    this.store.patch(updated);
  }

  findByLink(link: string, items?: LpxNavbarItem[]) {
    return this.findByProp('link', link, items);
  }

  expandItemByLink$() {
    return this.router.events.pipe(
      filter((e) => e instanceof NavigationEnd),
      tap(() => this.expandItems()),
    );
  }

  expandItems() {
    if (!this.store.state.length) {
      return;
    }

    const route = this.getRouteItem();
    if (!route?.item) {
      // Keep current expand/selected state when the URL is not in the menu
      // (e.g. transient NavigationEnd).
      this.expandedLocationKey = null;
      return;
    }

    const locationKey = route.location.join('.');
    if (locationKey === this.expandedLocationKey) {
      return;
    }

    const expanded = this.calculateExpandState(this.store.state, [
      ...route.location,
    ]);
    this.store.patch(expanded);
    this.expandedLocationKey = locationKey;
  }

  getRouteItem() {
    const path = this.router.url.split(/[?#]/)[0];
    const normalized = this.routeCultureUrl.normalizeForMenuMatch(path);
    return this.findByLink(normalized);
  }

  calculateExpandState(
    items: LpxNavbarItem[],
    indexes: Array<number>,
  ): LpxNavbarItem[] {
    const matchIndex = indexes.shift();
    if (matchIndex === undefined) {
      return items;
    }

    return items.reduce((acc, item, index) => {
      if (index === matchIndex) {
        return [
          ...acc,
          {
            ...item,
            expanded: true,
            selected: true,
            children: this.calculateExpandState(item.children || [], indexes),
          },
        ];
      }
      const newItem = {
        ...item,
        ...(item.children
          ? { children: this.collapseChildren(item.children) }
          : {}),
      };
      return [...acc, { ...newItem, expanded: false, selected: false }];
    }, [] as LpxNavbarItem[]);
  }

  collapseChildren(children: Array<LpxNavbarItem>): Array<LpxNavbarItem> {
    return [
      ...children.map((child) => ({
        ...child,
        expanded: false,
        selected: false,
        children: child.children ? this.collapseChildren(child.children) : [],
      })),
    ];
  }

  private addChildrenByLocation(
    items: LpxNavbarItem[],
    location: number[],
    linkPrefix: string,
    menuItems: LpxNavbarItem[],
  ): LpxNavbarItem[] {
    const [currentIndex, ...restLocation] = location;

    return items.map((item, index) => {
      if (index !== currentIndex) {
        return item;
      }

      const currentLink = `${linkPrefix}/${item.containerLink}`;

      // We reached the target item; append new children to it.
      if (!restLocation.length) {
        const existingChildren = item.children || [];
        const newChildren = this.addContainerLinks(menuItems, currentLink);

        return {
          ...item,
          children: [...existingChildren, ...newChildren],
        };
      }

      // We are still traversing the path; continue recursively on children.
      return {
        ...item,
        children: this.addChildrenByLocation(
          item.children || [],
          restLocation,
          currentLink,
          menuItems,
        ),
      };
    });
  }

  private findById(id: string, items?: LpxNavbarItem[]) {
    return this.findByProp('id', id, items);
  }

  private findByProp(
    prop: keyof LpxNavbarItem,
    value: string,
    items?: LpxNavbarItem[],
  ) {
    const navbarItems = items || this.store.state;
    const cleanValue = this.normalizeLink(value);

    let bestMatch: LpxNavbarItem | undefined;
    let bestMatchLocation: number[] = [];
    let bestMatchLength = 0;

    const isValidSegmentPrefix = (candidate: string): boolean => {
      if (!candidate || !cleanValue.startsWith(candidate)) {
        return false;
      }

      const isExactMatch = cleanValue.length === candidate.length;
      const hasPathSeparator = cleanValue[candidate.length] === '/';

      return isExactMatch || hasPathSeparator;
    };

    const searchTree = (
      nodes: LpxNavbarItem[],
      currentPath: number[] = [],
    ): { item?: LpxNavbarItem; location: number[] } => {
      for (let i = 0; i < nodes.length; i++) {
        const node = nodes[i];
        const nodePath = [...currentPath, i];
        const nodeValue =
          prop === 'link'
            ? this.normalizeLink(node[prop] as string)
            : (node[prop] as unknown as string | undefined);

        // Skip nodes without the property we're searching for
        if (!nodeValue) {
          if (node.children?.length) {
            const childResult = searchTree(node.children, nodePath);
            if (childResult.item) return childResult;
          }
          continue;
        }

        // For non-link properties, only exact matches count
        if (prop !== 'link') {
          if (nodeValue === cleanValue) {
            return { item: node, location: nodePath };
          }
        }

        // For link property, handle exact and prefix matches
        if (prop === 'link') {
          // Exact match - return immediately
          if (nodeValue === cleanValue) {
            return { item: node, location: nodePath };
          }

          // Track best prefix match (longest valid ancestor path)
          const isLongerMatch = nodeValue.length > bestMatchLength;
          if (isValidSegmentPrefix(nodeValue) && isLongerMatch) {
            bestMatch = node;
            bestMatchLocation = nodePath;
            bestMatchLength = nodeValue.length;
          }
        }

        // Recursively search children
        if (node.children?.length) {
          const childResult = searchTree(node.children, nodePath);
          if (childResult.item) {
            return childResult;
          }
        }
      }

      // No exact match found, return best prefix match
      return { item: bestMatch, location: bestMatchLocation };
    };

    return searchTree(navbarItems);
  }

  private normalizeLink(value?: string): string {
    const clean = (value || '').split(/[?#]/)[0];
    if (!clean) {
      return '/';
    }

    return clean.startsWith('/') ? clean : `/${clean}`;
  }

  private addContainerLinks(
    items: LpxNavbarItem[],
    link = '',
  ): LpxNavbarItem[] {
    return items.map((item) => ({
      ...item,
      ...(item.link && link ? { link: `${link}/${item.link}` } : {}),
      children: this.addContainerLinks(
        item.children || [],
        `${link ? link + '/' : ''}${item.containerLink || ''}`,
      ),
    }));
  }
}
