import { Injectable, DOCUMENT, inject } from '@angular/core';
import { LPX_STYLE_FINAL } from './tokens';
import { LpxStyle, LpxStyles } from './models';

import { BehaviorSubject } from 'rxjs';

@Injectable({
  providedIn: 'root',
})
export class StyleService {
  private initialStyles = inject<LpxStyles>(LPX_STYLE_FINAL);
  private document = inject<Document>(DOCUMENT);

  lastInjectedStyle: HTMLLinkElement | null = null;

  initialized$ = new BehaviorSubject<boolean>(false);

  async initStyles(direction: 'rtl' | 'ltr') {
    const cssExtension = direction === 'rtl' ? '.rtl' : '';

    for (const style of this.initialStyles) {
      const href = `${style.bundleName}${cssExtension}.css`;
      const selector = `
        link[rel="stylesheet"][href$="${href}"],
        link[rel="stylesheet"]#${style.bundleName}
      `;

      const isAlreadyLoaded = !!this.document.querySelector(selector);
      if (isAlreadyLoaded) {
        continue;
      }

      await this.loadStyle(style, direction);
    }
    this.initialized$.next(true);
  }

  async loadStyle(
    style: LpxStyle,
    direction: 'ltr' | 'rtl',
  ): Promise<HTMLStyleElement | void> {
    return new Promise((resolve) => {
      const linkElement = this.createLinkElem(style, direction, resolve);

      // Find styles.css to insert before it
      const stylesCss = this.document.querySelector(
        'link[rel="stylesheet"][href*="styles"]',
      );

      if (stylesCss) {
        stylesCss.insertAdjacentElement('beforebegin', linkElement);
      } else {
        this.document.head.appendChild(linkElement);
      }

      this.lastInjectedStyle = linkElement;
      resolve(linkElement);
    });
  }

  async replaceStyle<T extends LpxStyle>(
    style: T,
    direction: 'rtl' | 'ltr',
  ): Promise<HTMLStyleElement | void> {
    const loaded = this.document.querySelector(`link#${style.bundleName}`);
    if (loaded) {
      loaded.remove();
    }
    return this.loadStyle(style, direction);
  }

  async reloadInitialStyles(direction: 'rtl' | 'ltr') {
    for (const style of this.initialStyles) {
      await this.replaceStyle(style, direction);
    }
  }

  createLinkElem(
    style: LpxStyle,
    direction: 'rtl' | 'ltr',
    resolve: (param: any) => void,
  ): HTMLLinkElement {
    const linkElem = this.document.createElement('link');
    linkElem.rel = 'stylesheet';
    linkElem.id = style.bundleName;
    linkElem.href = `${style.bundleName}${
      direction === 'rtl' ? '.rtl' : ''
    }.css`;
    linkElem.onload = () => {
      resolve(linkElem);
    };
    return linkElem;
  }
}
