import { DOCUMENT, inject, PLATFORM_ID, provideAppInitializer, Injector, runInInjectionContext } from '@angular/core';
import { LanguageService } from '../services/language';
import { StyleService } from '../style';
import {
  distinctUntilKeyChanged,
  filter,
  switchMap,
  take,
} from 'rxjs/operators';
import { isPlatformBrowser } from '@angular/common';

export function createDirectionProvider(listenDirection: boolean) {
  return provideAppInitializer(() => {
    if (listenDirection) {
      listenDirectionChange();
    }
  });
}
// subscribe to direction from documentElement and load direction stylesheet
export function listenDirectionChange() {
  const languageService = inject(LanguageService);
  const styleService = inject(StyleService);
  const doc = inject(DOCUMENT) as Document;
  const platformId = inject(PLATFORM_ID);

  if (!isPlatformBrowser(platformId)) {
    return Promise.resolve();
  }

  return new Promise((resolve) => {
    styleService.initialized$
      .pipe(
        filter(Boolean),
        take(1),
        switchMap(() => languageService.languageChange$),
        distinctUntilKeyChanged('isRTL'),
      )
      .subscribe(async (lang) => {
        const direction = lang?.isRTL ? 'rtl' : 'ltr';
        const documentElement = (doc?.documentElement || ({} as HTMLElement)) as HTMLElement;
        if (documentElement && documentElement.dir !== direction) {
          documentElement.dir = direction;
        }
        await styleService.reloadInitialStyles(direction);
        resolve(null);
      });
  });
}
