import { ModuleWithProviders, NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import {
  LpxIconSettings,
  provideLpxCore,
  SKIP_DEFAULTS,
  withIcon,
} from '../../providers';
import { IconComponent } from './icon.component';

@NgModule({
  imports: [CommonModule, IconComponent],
  exports: [IconComponent],
})
export class LpxIconModule {
  /**
   * @deprecated `LpxIconModule.forRoot()` is deprecated. You can use `provideLpxCore` **function** instead.
   */
  static forRoot(
    options?: LpxIconSettings,
  ): ModuleWithProviders<LpxIconModule> {
    return {
      ngModule: LpxIconModule,
      providers: [provideLpxCore(SKIP_DEFAULTS, withIcon(options))],
    };
  }
}
