import { ModuleWithProviders, NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { LpxVisibleDirective } from './directives/visible.directive';
import {
  LpxCoreOptions,
  provideLpxCore,
  withLpxCoreOptions,
} from './providers';

@NgModule({
  imports: [CommonModule, LpxVisibleDirective],
})
export class LpxCoreModule {
  /**
   * @deprecated `LpxCoreModule.forRoot()` is deprecated. You can use `provideLpxCore` **function** instead.
   */
  static forRoot(options?: LpxCoreOptions): ModuleWithProviders<LpxCoreModule> {
    return {
      ngModule: LpxCoreModule,
      providers: [provideLpxCore(...withLpxCoreOptions(options))],
    };
  }
}
