import { Component, inject, Input, ViewEncapsulation } from '@angular/core';
import { LEPTON_X_ICON_SET, ICON_MAP_TYPE } from './icon.token';

@Component({
  selector: 'lpx-icon',
  template: `
    <i class="lpx-icon" [class]="styleClass" aria-hidden="true"></i>
  `,
  encapsulation: ViewEncapsulation.None,
  imports: [],
})
export class IconComponent {
  public iconSet = inject<ICON_MAP_TYPE>(LEPTON_X_ICON_SET);

  @Input() iconClass?: keyof ICON_MAP_TYPE | string;

  get styleClass() {
    return (
      this.iconSet[this.iconClass as keyof ICON_MAP_TYPE] || this.iconClass
    );
  }
}
