import { Component, inject, ViewEncapsulation } from '@angular/core';
import { RouterLink } from '@angular/router';
import { NgTemplateOutlet, AsyncPipe } from '@angular/common';
import { ClickOutsideDirective } from '../../directives/click-outside/click-outside.directive';
import { ToObservablePipe } from '../../pipes/to-observable/to-observable.pipe';
import { ICON_MAP, IconComponent } from '../icon';
import { BreadcrumbItem, BreadcrumbService } from './breadcrumb.service';

@Component({
  selector: 'lpx-breadcrumb',
  templateUrl: './breadcrumb.component.html',
  encapsulation: ViewEncapsulation.None,
  imports: [
    ClickOutsideDirective,
    IconComponent,
    NgTemplateOutlet,
    RouterLink,
    AsyncPipe,
    ToObservablePipe,
  ],
})
export class BreadcrumbComponent {
  public service = inject(BreadcrumbService);
  icon = ICON_MAP;

  onClick(item: BreadcrumbItem): void {
    if (item.children) {
      item.expanded = !item.expanded;
    }
  }

  // TODO: close dropdown when click outside
}
