import { ModuleWithProviders, NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RouterModule } from '@angular/router';
import { ToObservableModule, LpxTranslateModule } from '../../pipes';
import { LpxVisibleDirective } from '../../directives/visible.directive';
import { LpxBrandLogoModule } from '../brand-logo/brand-logo.module';
import { LpxIconModule } from '../icon/icon.module';
import { NavbarComponent } from './navbar.component';
import { SubNavbarComponent } from './sub-navbar/sub-navbar.component';
import { NavbarRoutesComponent } from './navbar-routes/navbar-routes.component';
import { NavbarRoutesDirective } from './navbar-routes/navbar-routes.directive';
import {
  LpxNavbarSettings,
  provideLpxCore,
  SKIP_DEFAULTS,
  withNavbar,
  withNavbarChild,
} from '../../providers';

const exportedDeclarations = [
  NavbarComponent,
  SubNavbarComponent,
  NavbarRoutesComponent,
  NavbarRoutesDirective,
];

@NgModule({
  imports: [
    CommonModule,
    FormsModule,
    RouterModule,
    LpxBrandLogoModule,
    LpxIconModule,
    ToObservableModule,
    LpxTranslateModule,
    LpxVisibleDirective,
    ...exportedDeclarations,
  ],
  exports: [...exportedDeclarations],
})
export class LpxNavbarModule {
  /**
   * @deprecated `LpxNavbarModule.forRoot()` is deprecated. You can use `provideLpxCore` **function** instead.
   */
  static forRoot(
    options: LpxNavbarSettings = {},
  ): ModuleWithProviders<LpxNavbarModule> {
    return {
      ngModule: LpxNavbarModule,
      providers: [provideLpxCore(SKIP_DEFAULTS, withNavbar(options))],
    };
  }

  /**
   * @deprecated `LpxNavbarModule.forChild()` is deprecated. You can use `provideLpxCore` **function** instead.
   */
  static forChild(
    options: Omit<LpxNavbarSettings, 'menuItems'> = {},
  ): ModuleWithProviders<LpxNavbarModule> {
    return {
      ngModule: LpxNavbarModule,
      providers: [provideLpxCore(SKIP_DEFAULTS, withNavbarChild(options))],
    };
  }
}
