import { RouterLink } from '@angular/router';
import { Component, inject, input, ViewEncapsulation } from '@angular/core';
import { LOGO_APP_NAME_TOKEN, LOGO_URL_TOKEN } from '@abp/ng.theme.shared';
import { Layouts } from '../../enums';

@Component({
  selector: 'lpx-brand-logo',
  templateUrl: './brand-logo.component.html',
  encapsulation: ViewEncapsulation.None,
  imports: [RouterLink],
})
export class BrandLogoComponent {
  layout = input<Layouts>(Layouts.sideMenu);

  layoutOptions = Layouts;

  protected readonly logoUrl: string | null = inject(LOGO_URL_TOKEN, {
    optional: true,
  });

  protected readonly appName =
    inject(LOGO_APP_NAME_TOKEN, {
      optional: true,
    }) ?? 'ProjectName';
}
