import { inject, PLATFORM_ID, Provider } from '@angular/core';
import { WINDOW } from '../tokens/window.token';
import { isPlatformBrowser } from '@angular/common';

export function createWindowProvider(windowObj: Window | undefined): Provider {
  return { provide: WINDOW, useFactory: () => {
      if (windowObj) {
        return windowObj;
      } else {
        const platformId = inject(PLATFORM_ID);
        return isPlatformBrowser(platformId) ? window : undefined;
      }
    }
  }
}
