import {
  EnvironmentProviders,
  inject,
  makeEnvironmentProviders,
  provideAppInitializer,
  Provider,
  Type,
} from '@angular/core';
import {
  BreadcrumbRouteListenerService,
  CONTENT_AFTER_ROUTES,
  CONTENT_BEFORE_ROUTES,
  ICON_MAP,
  ICON_MAP_TYPE,
  LEPTON_X_ICON_SET,
  LPX_MENU_ITEMS,
  LpxNavbarItem,
} from '../components';
import { ResponsiveBreakpoints } from '../directives';
import {
  LanguageService,
  LanguageTranslateDefaults,
  LPX_LANGUAGE,
  LPX_TRANSLATE_TOKEN,
  LPX_TRANSLATE_PROVIDERS,
  LpxLanguageModuleOptions,
  LpxTranslate,
} from '../services';
import {
  createDirectionProvider,
  createResponsiveProvider,
  LPX_STYLE_PROVIDERS,
  createWindowProvider,
} from './';

export interface LpxIconSettings {
  iconSet?: ICON_MAP_TYPE;
}

export interface LpxNavbarSettings {
  menuItems?: LpxNavbarItem[];
  contentAfterRoutes?: Type<any>[];
  contentBeforeRoutes?: Type<any>[];
}

export interface LpxCoreOptions {
  responsiveSettings?: ResponsiveBreakpoints;
  window?: Window;
  iconSettings?: LpxIconSettings;
  languageSettings?: LpxLanguageModuleOptions;
  navbarSettings?: LpxNavbarSettings;
  texts?: LpxTranslate[];
  listenDirectionChanges?: boolean;
}

export enum LpxCoreFeatureKind {
  Options,
  Icon,
  Language,
  Navbar,
  NavbarChild,
  SkipDefaults,
}

export interface LpxCoreFeature<KindT extends LpxCoreFeatureKind> {
  ɵkind: KindT;
  ɵproviders: (Provider | EnvironmentProviders)[];
}

function makeLpxCoreFeature<KindT extends LpxCoreFeatureKind>(
  kind: KindT,
  providers: (Provider | EnvironmentProviders)[],
): LpxCoreFeature<KindT> {
  return {
    ɵkind: kind,
    ɵproviders: providers,
  };
}

export const SKIP_DEFAULTS = makeLpxCoreFeature(
  LpxCoreFeatureKind.SkipDefaults,
  [],
);

export function withIcon(
  iconSettings = {} as LpxIconSettings,
): LpxCoreFeature<LpxCoreFeatureKind.Icon> {
  return makeLpxCoreFeature(LpxCoreFeatureKind.Icon, [
    {
      provide: LEPTON_X_ICON_SET,
      useValue: iconSettings.iconSet || ICON_MAP,
    },
  ]);
}

export function withLanguage(
  languageOptions = {} as LpxLanguageModuleOptions,
): LpxCoreFeature<LpxCoreFeatureKind.Language> {
  return makeLpxCoreFeature(LpxCoreFeatureKind.Language, [
    {
      provide: LPX_LANGUAGE,
      useValue: languageOptions.languages || [],
    },
    {
      provide: LPX_TRANSLATE_TOKEN,
      useValue: [LanguageTranslateDefaults],
      multi: true,
    },
    LanguageService,
  ]);
}

export function withNavbar(
  navbarOptions = {} as LpxNavbarSettings,
): LpxCoreFeature<LpxCoreFeatureKind.Navbar> {
  const { menuItems, contentBeforeRoutes, contentAfterRoutes } = navbarOptions;
  return makeLpxCoreFeature(LpxCoreFeatureKind.Navbar, [
    {
      provide: LPX_MENU_ITEMS,
      useValue: menuItems || [],
    },
    {
      provide: CONTENT_AFTER_ROUTES,
      useValue: contentAfterRoutes || [],
      multi: true,
    },
    {
      provide: CONTENT_BEFORE_ROUTES,
      useValue: contentBeforeRoutes || [],
      multi: true,
    },
  ]);
}

export function withNavbarChild(
  navbarChildOptions = {} as Omit<LpxNavbarSettings, 'menuItems'>,
): LpxCoreFeature<LpxCoreFeatureKind.NavbarChild> {
  return makeLpxCoreFeature(LpxCoreFeatureKind.NavbarChild, [
    {
      provide: CONTENT_AFTER_ROUTES,
      useValue: navbarChildOptions.contentAfterRoutes || [],
      multi: true,
    },
    {
      provide: CONTENT_BEFORE_ROUTES,
      useValue: navbarChildOptions.contentBeforeRoutes || [],
      multi: true,
    },
  ]);
}

export function withLpxCoreOptions(
  options = {} as LpxCoreOptions,
): LpxCoreFeature<LpxCoreFeatureKind>[] {
  const {
    responsiveSettings,
    window,
    iconSettings,
    languageSettings,
    navbarSettings,
    listenDirectionChanges,
  } = options;

  const iconOptions = withIcon(iconSettings);
  const languageOptions = withLanguage(languageSettings);
  const navbarOptions = withNavbar(navbarSettings);

  return [
    iconOptions,
    languageOptions,
    navbarOptions,
    makeLpxCoreFeature(LpxCoreFeatureKind.Options, [
      createDirectionProvider(listenDirectionChanges || true),
      createResponsiveProvider(responsiveSettings),
      createWindowProvider(window),
    ]),
  ];
}

export function provideLpxBreadcrumb(): EnvironmentProviders {
  return provideAppInitializer(() => {
    const breadcrumb = inject(BreadcrumbRouteListenerService);
    breadcrumb.subscribeRoute();
  });
}

export function provideLpxCore(
  ...features: LpxCoreFeature<LpxCoreFeatureKind>[]
): EnvironmentProviders {
  const providers: (Provider | EnvironmentProviders)[] = [];
  const skipDefaults = features.some(
    (feature) => feature.ɵkind === LpxCoreFeatureKind.SkipDefaults,
  );

  if (!skipDefaults) {
    providers.push(
      provideLpxBreadcrumb(),
      ...LPX_STYLE_PROVIDERS,
      ...LPX_TRANSLATE_PROVIDERS,
    );
  }

  features.forEach(({ ɵproviders }) => providers.push(...ɵproviders));

  return makeEnvironmentProviders(providers);
}
