import { Injectable } from '@angular/core';
import { DataStore } from '../../utils/data-store';

export interface FooterLink {
  link: string;
  text: string;
}

export interface FooterNav {
  brandName: string;
  brandUrl: string;
  authorName: string;
  authorUrl: string;
  links?: FooterLink[];
}

const DEFAULT_FOOTER_DATA: FooterNav = {
  brandName: 'Lepton Theme',
  brandUrl: 'https://leptontheme.com/',
  authorName: 'Volosoft',
  authorUrl: 'https://volosoft.com/',
  links: [
    { text: 'About', link: '' },
    { text: 'Privacy', link: '' },
    { text: 'Contact', link: '' }
  ]
};

@Injectable({
  providedIn: 'root',
})
export class FooterLinksService {
  private store = new DataStore(DEFAULT_FOOTER_DATA);
  footerInfo$ = this.store.sliceState((state) => state);

  setFooterInfo(links: FooterNav) {
    this.store.set(links);
  } 
}
