import { ModuleWithProviders, NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { LpxLanguageModuleOptions } from './models';
import { provideLpxCore, SKIP_DEFAULTS, withLanguage } from '../../providers';

@NgModule({
  declarations: [],
  imports: [CommonModule],
})
export class LpxLanguageModule {
  /**
   * @deprecated `LpxLanguageModule.forRoot()` is deprecated. You can use `provideLpxCore` **function** instead.
   */
  static forRoot(
    options?: LpxLanguageModuleOptions,
  ): ModuleWithProviders<LpxLanguageModule> {
    return {
      ngModule: LpxLanguageModule,
      providers: [provideLpxCore(SKIP_DEFAULTS, withLanguage(options))],
    };
  }
}
